<?php

declare(strict_types=1);

use EventMenu\Core\Auth;
use EventMenu\Core\Database;
use EventMenu\Core\Security;

Auth::requirePermission('events.manage');$tenantId=em_require_tenant();$unitId=Auth::unitId();$tenantStmt=$pdo->prepare('SELECT slug FROM tenants WHERE id=?');$tenantStmt->execute([$tenantId]);$tenantSlug=(string)$tenantStmt->fetchColumn();
if($_SERVER['REQUEST_METHOD']==='POST'){em_post_csrf();$action=(string)($_POST['action']??'');try{
    if($action==='event-save'){$id=(int)($_POST['id']??0);$name=trim((string)($_POST['name']??''));$starts=(string)($_POST['starts_at']??'');$status=(string)($_POST['status']??'draft');$u=(int)($_POST['unit_id']??0);if($name===''||$starts===''||!in_array($status,['draft','published','closed','cancelled'],true))throw new RuntimeException('Evento inválido.');$slug=em_slug((string)($_POST['slug']??$name));$ends=(string)($_POST['ends_at']??'');$starts=str_replace('T',' ',$starts);$ends=$ends?str_replace('T',' ',$ends):null;if($id){$s=$pdo->prepare('UPDATE events SET unit_id=?,name=?,slug=?,description=?,venue=?,address=?,starts_at=?,ends_at=?,status=?,banner_url=? WHERE id=? AND tenant_id=?');$s->execute([$u?:null,$name,$slug,trim((string)($_POST['description']??'')),trim((string)($_POST['venue']??'')),trim((string)($_POST['address']??'')),$starts,$ends,$status,trim((string)($_POST['banner_url']??''))?:null,$id,$tenantId]);}else{$s=$pdo->prepare('INSERT INTO events (tenant_id,unit_id,name,slug,description,venue,address,starts_at,ends_at,status,banner_url) VALUES (?,?,?,?,?,?,?,?,?,?,?)');try{$s->execute([$tenantId,$u?:null,$name,$slug,trim((string)($_POST['description']??'')),trim((string)($_POST['venue']??'')),trim((string)($_POST['address']??'')),$starts,$ends,$status,trim((string)($_POST['banner_url']??''))?:null]);}catch(PDOException){$slug.='-'.substr(bin2hex(random_bytes(3)),0,5);$s->execute([$tenantId,$u?:null,$name,$slug,trim((string)($_POST['description']??'')),trim((string)($_POST['venue']??'')),trim((string)($_POST['address']??'')),$starts,$ends,$status,trim((string)($_POST['banner_url']??''))?:null]);}$id=(int)$pdo->lastInsertId();}Auth::audit('event.saved','event',(string)$id);em_flash('ok','Evento salvo.');em_go('events',['edit'=>$id]);}
    if($action==='batch-save'){$eventId=(int)($_POST['event_id']??0);$id=(int)($_POST['id']??0);$e=$pdo->prepare('SELECT id FROM events WHERE id=? AND tenant_id=?');$e->execute([$eventId,$tenantId]);if(!$e->fetchColumn())throw new RuntimeException('Evento inválido.');$name=trim((string)($_POST['name']??''));$price=(int)round((float)str_replace(',','.',(string)($_POST['price']??'0'))*100);$qty=max(1,(int)($_POST['quantity_total']??1));$start=(string)($_POST['sales_start']??'');$end=(string)($_POST['sales_end']??'');$start=$start?str_replace('T',' ',$start):null;$end=$end?str_replace('T',' ',$end):null;if($name===''||$price<0)throw new RuntimeException('Lote inválido.');if($id){$lock=$pdo->prepare('SELECT quantity_sold,quantity_reserved FROM ticket_batches WHERE id=? AND event_id=? FOR UPDATE');$lock->execute([$id,$eventId]);$old=$lock->fetch();if(!$old)throw new RuntimeException('Lote não encontrado.');if($qty<(int)$old['quantity_sold']+(int)$old['quantity_reserved'])throw new RuntimeException('Quantidade total não pode ser menor que vendidos + reservados.');$pdo->prepare('UPDATE ticket_batches SET name=?,price_cents=?,quantity_total=?,sales_start=?,sales_end=?,active=? WHERE id=? AND event_id=?')->execute([$name,$price,$qty,$start,$end,isset($_POST['active'])?1:0,$id,$eventId]);}else{$pdo->prepare('INSERT INTO ticket_batches (event_id,name,price_cents,quantity_total,sales_start,sales_end,active) VALUES (?,?,?,?,?,?,1)')->execute([$eventId,$name,$price,$qty,$start,$end]);$id=(int)$pdo->lastInsertId();}Auth::audit('ticket_batch.saved','ticket_batch',(string)$id);em_flash('ok','Lote salvo.');em_go('events',['edit'=>$eventId]);}
    if($action==='duplicate'){Database::transaction(function(PDO$db)use($tenantId){$id=(int)$_POST['id'];$s=$db->prepare('SELECT * FROM events WHERE id=? AND tenant_id=? FOR UPDATE');$s->execute([$id,$tenantId]);$e=$s->fetch();if(!$e)throw new RuntimeException('Evento não encontrado.');$slug=em_slug($e['slug'].'-copia-'.substr(bin2hex(random_bytes(2)),0,4));$db->prepare('INSERT INTO events (tenant_id,unit_id,name,slug,description,venue,address,starts_at,ends_at,status,banner_url) VALUES (?,?,?,?,?,?,?,?,?,"draft",?)')->execute([$tenantId,$e['unit_id'],$e['name'].' (cópia)',$slug,$e['description'],$e['venue'],$e['address'],$e['starts_at'],$e['ends_at'],$e['banner_url']]);$new=(int)$db->lastInsertId();$b=$db->prepare('SELECT * FROM ticket_batches WHERE event_id=? ORDER BY id');$b->execute([$id]);$ins=$db->prepare('INSERT INTO ticket_batches (event_id,name,price_cents,quantity_total,quantity_sold,quantity_reserved,sales_start,sales_end,active) VALUES (?,?,?, ?,0,0,?,?,?)');foreach($b->fetchAll()as$r)$ins->execute([$new,$r['name'],$r['price_cents'],$r['quantity_total'],$r['sales_start'],$r['sales_end'],$r['active']]);Auth::audit('event.duplicated','event',(string)$new,['source'=>$id]);$_SESSION['_flash']=['ok','Evento duplicado como rascunho.'];});em_go('events');}
    if($action==='delete'){$id=(int)$_POST['id'];Database::transaction(function(PDO$db)use($tenantId,$id){$s=$db->prepare('SELECT id,status FROM events WHERE id=? AND tenant_id=? FOR UPDATE');$s->execute([$id,$tenantId]);if(!$s->fetch())throw new RuntimeException('Evento não encontrado.');$c=$db->prepare('SELECT COUNT(*) FROM tickets WHERE event_id=?');$c->execute([$id]);if((int)$c->fetchColumn()>0){$db->prepare('UPDATE events SET status="cancelled" WHERE id=? AND tenant_id=?')->execute([$id,$tenantId]);Auth::audit('event.archived','event',(string)$id);$_SESSION['_flash']=['ok','Evento possui ingressos/histórico e foi cancelado, não excluído.'];}else{$db->prepare('DELETE FROM events WHERE id=? AND tenant_id=?')->execute([$id,$tenantId]);Auth::audit('event.deleted','event',(string)$id);$_SESSION['_flash']=['ok','Evento excluído.'];}});em_go('events');}
}catch(Throwable$e){em_flash('error',$e->getMessage());em_go('events');}}
$editId=(int)($_GET['edit']??0);$edit=null;$batches=[];if($editId){$s=$pdo->prepare('SELECT * FROM events WHERE id=? AND tenant_id=?');$s->execute([$editId,$tenantId]);$edit=$s->fetch()?:null;if($edit){$b=$pdo->prepare('SELECT * FROM ticket_batches WHERE event_id=? ORDER BY id');$b->execute([$editId]);$batches=$b->fetchAll();}}$units=$pdo->prepare('SELECT id,name FROM business_units WHERE tenant_id=? AND status="active" ORDER BY name');$units->execute([$tenantId]);$units=$units->fetchAll();$sql='SELECT e.*,bu.name unit_name,(SELECT COALESCE(SUM(quantity_sold),0) FROM ticket_batches b WHERE b.event_id=e.id) sold,(SELECT COALESCE(SUM(quantity_reserved),0) FROM ticket_batches b WHERE b.event_id=e.id) reserved,(SELECT COUNT(*) FROM tickets t WHERE t.event_id=e.id) tickets_count FROM events e LEFT JOIN business_units bu ON bu.id=e.unit_id WHERE e.tenant_id=?';$args=[$tenantId];if($unitId){$sql.=' AND (e.unit_id IS NULL OR e.unit_id=?)';$args[]=$unitId;}$sql.=' ORDER BY e.starts_at DESC';$s=$pdo->prepare($sql);$s->execute($args);$events=$s->fetchAll();$editBatchId=(int)($_GET['batch']??0);$editBatch=null;if($editBatchId&&$edit){foreach($batches as$b)if((int)$b['id']===$editBatchId)$editBatch=$b;}
em_header('Eventos','events');?>
<div class="grid" style="grid-template-columns:minmax(310px,1fr) minmax(0,2fr)"><section class="card"><h2><?= $edit?'Editar evento':'Novo evento' ?></h2><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="event-save"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><label class="span-2">Nome<input name="name" required value="<?= Security::e($edit['name']??'') ?>"></label><label>Unidade<select name="unit_id"><option value="0">Todas / geral</option><?php foreach($units as$u):?><option value="<?= (int)$u['id'] ?>"<?= em_selected($edit['unit_id']??$unitId,$u['id']) ?>><?= Security::e($u['name']) ?></option><?php endforeach;?></select></label><label>Status<select name="status"><?php foreach(['draft'=>'Rascunho','published'=>'Publicado','closed'=>'Encerrado','cancelled'=>'Cancelado']as$v=>$l):?><option value="<?= $v ?>"<?= em_selected($edit['status']??'draft',$v) ?>><?= $l ?></option><?php endforeach;?></select></label><label class="span-2">Slug público<input name="slug" value="<?= Security::e($edit['slug']??'') ?>"></label><label>Início<input type="datetime-local" name="starts_at" required value="<?= $edit?Security::e(date('Y-m-d\TH:i',strtotime($edit['starts_at']))):'' ?>"></label><label>Fim<input type="datetime-local" name="ends_at" value="<?= $edit&&$edit['ends_at']?Security::e(date('Y-m-d\TH:i',strtotime($edit['ends_at']))):'' ?>"></label><label>Local<input name="venue" value="<?= Security::e($edit['venue']??'') ?>"></label><label>Banner URL<input type="url" name="banner_url" value="<?= Security::e($edit['banner_url']??'') ?>"></label><label class="span-2">Endereço<input name="address" value="<?= Security::e($edit['address']??'') ?>"></label><label class="span-2">Descrição<textarea name="description"><?= Security::e($edit['description']??'') ?></textarea></label><button class="primary span-2">Salvar evento</button></form><?php if($edit):?><hr style="border-color:var(--line);margin:24px 0"><h2><?= $editBatch?'Editar lote':'Novo lote' ?></h2><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="batch-save"><input type="hidden" name="event_id" value="<?= (int)$edit['id'] ?>"><input type="hidden" name="id" value="<?= (int)($editBatch['id']??0) ?>"><label>Nome<input name="name" required value="<?= Security::e($editBatch['name']??'') ?>"></label><label>Preço<input name="price" inputmode="decimal" required value="<?= $editBatch?Security::e(number_format($editBatch['price_cents']/100,2,',','')):'' ?>"></label><label>Quantidade<input type="number" name="quantity_total" min="1" required value="<?= (int)($editBatch['quantity_total']??1) ?>"></label><label>Início venda<input type="datetime-local" name="sales_start" value="<?= $editBatch&&$editBatch['sales_start']?Security::e(date('Y-m-d\TH:i',strtotime($editBatch['sales_start']))):'' ?>"></label><label>Fim venda<input type="datetime-local" name="sales_end" value="<?= $editBatch&&$editBatch['sales_end']?Security::e(date('Y-m-d\TH:i',strtotime($editBatch['sales_end']))):'' ?>"></label><label class="checkbox"><input type="checkbox" name="active"<?= em_checked($editBatch?($editBatch['active']??0):1) ?>> Ativo</label><button class="secondary span-2"><?= $editBatch?'Salvar lote':'Adicionar lote' ?></button></form><?php endif;?></section><section><div class="card"><div class="section-head"><h2>Eventos</h2><span class="muted"><?= count($events) ?> cadastrados</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Evento</th><th>Unidade</th><th>Data</th><th>Status</th><th>Ingressos</th><th></th></tr></thead><tbody><?php foreach($events as$e):?><tr><td><strong><?= Security::e($e['name']) ?></strong><br><a href="<?= Security::e(em_url('/evento.php?empresa='.urlencode($tenantSlug).'&evento='.urlencode($e['slug']))) ?>" target="_blank">Página pública</a></td><td><?= Security::e($e['unit_name']??'Geral') ?></td><td><?= Security::e(date('d/m/Y H:i',strtotime($e['starts_at']))) ?></td><td><span class="badge"><?= Security::e(em_status_label($e['status'])) ?></span></td><td><?= (int)$e['sold'] ?> pagos · <?= (int)$e['reserved'] ?> reservados</td><td><div class="actions"><a class="button secondary" href="<?= Security::e(em_url('/?route=events&edit='.(int)$e['id'])) ?>">Editar</a><form method="post"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="duplicate"><input type="hidden" name="id" value="<?= (int)$e['id'] ?>"><button class="secondary">Duplicar</button></form><form method="post" onsubmit="return confirm('Excluir/cancelar este evento?')"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$e['id'] ?>"><button class="secondary"><?= $e['tickets_count']?'Cancelar':'Excluir' ?></button></form></div></td></tr><?php endforeach;?></tbody></table></div></div><?php if($edit):?><div class="card" style="margin-top:18px"><h2>Lotes de <?= Security::e($edit['name']) ?></h2><div class="table-wrap"><table class="table"><thead><tr><th>Lote</th><th>Preço</th><th>Total</th><th>Vendidos</th><th>Reservados</th><th>Disponíveis</th><th></th></tr></thead><tbody><?php foreach($batches as$b):$available=max(0,(int)$b['quantity_total']-(int)$b['quantity_sold']-(int)$b['quantity_reserved']);?><tr><td><?= Security::e($b['name']) ?></td><td><?= em_money($b['price_cents']) ?></td><td><?= (int)$b['quantity_total'] ?></td><td><?= (int)$b['quantity_sold'] ?></td><td><?= (int)$b['quantity_reserved'] ?></td><td><strong><?= $available ?></strong></td><td><a class="button secondary" href="<?= Security::e(em_url('/?route=events&edit='.$editId.'&batch='.(int)$b['id'])) ?>">Editar</a></td></tr><?php endforeach;?></tbody></table></div></div><?php endif;?></section></div><?php em_footer();
